<script type="module">
  import * as THREE from 'three';
  import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

  function initSHViewer(){
    const container = document.getElementById('sh-viewer');
    if(!container || container.dataset.inited) return;
    container.dataset.inited = '1';

    const w = container.clientWidth, h = container.clientHeight;
    const scene = new THREE.Scene();
    // 关键修改：移除 scene.background 强制设定，允许博客背景透出
    // scene.background = new THREE.Color(0x000010); 

    const camera = new THREE.PerspectiveCamera(45, w/h, 0.1, 100);
    camera.position.set(0, 0, 12);

    // 关键修改：开启 alpha 通道透明
    const renderer = new THREE.WebGLRenderer({antialias:true, alpha:true});
    renderer.setSize(w, h);
    renderer.setClearColor(0x000000, 0); // 完全透明
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.8;

    function shBasis(l, m, theta, phi){
      const s = Math.sin(theta), c = Math.cos(theta);
      if(l===0) return 0.282095;
      if(l===1 && m===-1) return 0.488603 * s * Math.sin(phi);
      if(l===1 && m=== 0) return 0.488603 * c;
      if(l===1 && m=== 1) return 0.488603 * s * Math.cos(phi);
      if(l===2 && m===-2) return 1.092548 * s*s * Math.sin(2*phi);
      if(l===2 && m===-1) return 1.092548 * s*c * Math.sin(phi);
      if(l===2 && m=== 0) return 0.315392 * (3*c*c - 1);
      if(l===2 && m=== 1) return 1.092548 * s*c * Math.cos(phi);
      if(l===2 && m=== 2) return 0.546274 * s*s * Math.cos(2*phi);
      return 0;
    }

    function makeSHLobe(l, m){
      const SEG = 48;
      const positions = [], colors = [], indices = [];
      for(let i=0; i<=SEG; i++){
        const theta = i / SEG * Math.PI;
        for(let j=0; j<=SEG; j++){
          const phi = j / SEG * 2 * Math.PI;
          const y = shBasis(l, m, theta, phi);
          const r = Math.abs(y) * 1.6;
          const x = r * Math.sin(theta) * Math.cos(phi);
          const yy = r * Math.cos(theta);
          const z = r * Math.sin(theta) * Math.sin(phi);
          positions.push(x, yy, z);
          // 稍微提亮了颜色以适应各种背景
          if(y >= 0) colors.push(0.98, 0.40, 0.35); 
          else colors.push(0.30, 0.65, 0.98);
        }
      }
      for(let i=0; i<SEG; i++){
        for(let j=0; j<SEG; j++){
          const a = i*(SEG+1)+j, b = a+1, cIdx = a+(SEG+1), d = cIdx+1;
          indices.push(a,b,cIdx, b,d,cIdx);
        }
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
      geo.setIndex(indices);
      geo.computeVertexNormals();
      const mat = new THREE.MeshStandardMaterial({
        vertexColors: true, flatShading: false,
        roughness: 0.4, metalness: 0.2
      });
      return new THREE.Mesh(geo, mat);
    }

    const ROW_Y = [3.0, 0, -3.0];
    const lobesByRow = [[[0,0]], [[1,-1],[1,0],[1,1]], [[2,-2],[2,-1],[2,0],[2,1],[2,2]]];
    const SPACING = 2.4;

    lobesByRow.forEach(function(row, rowIdx){
      const n = row.length;
      const startX = -(n-1) * SPACING * 0.5;
      row.forEach(function(lm, idx){
        const lobe = makeSHLobe(lm[0], lm[1]);
        lobe.position.set(startX + idx*SPACING, ROW_Y[rowIdx], 0);
        scene.add(lobe);
        const canvas = document.createElement('canvas');
        canvas.width = 128; canvas.height = 32;
        const ctx = canvas.getContext('2d');
        // 调整了文字绘制，使其在透明背景上也能清晰可见
        ctx.fillStyle = 'rgba(120, 120, 120, 0.8)'; 
        ctx.font = 'bold 18px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('Y_'+lm[0]+'^'+(lm[1]>=0?'+'+lm[1]:lm[1]), 64, 22);
        const tex = new THREE.CanvasTexture(canvas);
        const sprite = new THREE.Sprite(new THREE.SpriteMaterial({map:tex, transparent:true}));
        sprite.scale.set(1.4, 0.35, 1);
        sprite.position.set(startX + idx*SPACING, ROW_Y[rowIdx]-1.6, 0);
        scene.add(sprite);
      });
    });

    const amb = new THREE.AmbientLight(0xffffff, 0.6); scene.add(amb);
    const key = new THREE.DirectionalLight(0xffffff, 0.8);
    key.position.set(5,5,5); scene.add(key);
    const fill = new THREE.DirectionalLight(0x88aaff, 0.4);
    fill.position.set(-5,-3,2); scene.add(fill);

    function tick(){
      requestAnimationFrame(tick);
      controls.update();
      renderer.render(scene, camera);
    }
    tick();

    window.addEventListener('resize', function(){
      const nw = container.clientWidth, nh = container.clientHeight;
      camera.aspect = nw/nh; camera.updateProjectionMatrix();
      renderer.setSize(nw, nh);
    });
  }
  initSHViewer();
</script>
