    var GRID_X = 8, GRID_Y = 5;
    var PAD = 70;
    for(var iy=0; iy<GRID_Y; iy++){
      for(var ix=0; ix<GRID_X; ix++){
        probes.push({
          x: PAD + ix * (W - 2*PAD) / (GRID_X-1),
          y: 70 + iy * (H - 130) / (GRID_Y-1),
          irr: 0,
          meanDist: 100,
          meanDistSq: 10000
        });
      }
    }

    var light = {x: 150, y: 200, dragging: false};

    function segIntersectAABB(x0,y0,x1,y1, ax,ay,bx,by){
      var dx = x1-x0, dy = y1-y0;
      var tMin = 0, tMax = 1;
      if(Math.abs(dx) < 1e-6){
        if(x0<ax || x0>bx) return 1.0;
      } else {
        var t1 = (ax-x0)/dx, t2 = (bx-x0)/dx;
        var lo = Math.min(t1,t2), hi = Math.max(t1,t2);
        tMin = Math.max(tMin, lo); tMax = Math.min(tMax, hi);
      }
      if(Math.abs(dy) < 1e-6){
        if(y0<ay || y0>by) return 1.0;
      } else {
        var t1 = (ay-y0)/dy, t2 = (by-y0)/dy;
        var lo = Math.min(t1,t2), hi = Math.max(t1,t2);
        tMin = Math.max(tMin, lo); tMax = Math.min(tMax, hi);
      }
      if(tMin > tMax || tMin <= 0) return 1.0;
      return tMin;
    }
    function rayHitsWall(x0,y0, x1,y1){
      var minT = 1.0;
      for(var k=0;k<walls.length;k++){
        var w = walls[k];
        var t = segIntersectAABB(x0,y0,x1,y1, w.x, w.y, w.x+w.w, w.y+w.h);
        if(t < minT) minT = t;
      }
      return minT;
    }

    function update(){
      var cheb = document.getElementById('ddgi-cheb').checked;

      for(var i=0;i<probes.length;i++){
        var p = probes[i];
        var dx = light.x - p.x, dy = light.y - p.y;
        var dist = Math.sqrt(dx*dx + dy*dy);
        var t = rayHitsWall(p.x, p.y, light.x, light.y);

        var visible = (t >= 1.0);
        var irr = 0;

        if(visible){
          irr = 1.0 / (1.0 + dist*dist*0.0001);
        } else if(cheb){
          var nearestWall = 9999;
          for(var k=0;k<walls.length;k++){
            var ww = walls[k];
            var cx = Math.max(ww.x, Math.min(p.x, ww.x+ww.w));
            var cy = Math.max(ww.y, Math.min(p.y, ww.y+ww.h));
            var d = Math.sqrt((p.x-cx)*(p.x-cx)+(p.y-cy)*(p.y-cy));
            if(d < nearestWall) nearestWall = d;
          }
          p.meanDist = 0.95 * p.meanDist + 0.05 * nearestWall;
          p.meanDistSq = 0.95 * p.meanDistSq + 0.05 * nearestWall * nearestWall;
          var variance = Math.max(p.meanDistSq - p.meanDist*p.meanDist, 1);
          var diff = Math.max(dist - p.meanDist, 0);
          var pMax = variance / (variance + diff*diff);
          pMax = pMax * pMax;
          irr = pMax * 0.4 / (1.0 + dist*dist*0.0001);
        } else {
          irr = 0.5 / (1.0 + dist*dist*0.0001);
        }

        p.irr = 0.9 * p.irr + 0.1 * irr;
      }
    }

    function draw(){
      ctx.fillStyle = '#111116'; // 稍浅的内部纯黑，增强对比
      ctx.fillRect(0,0,W,H);

      for(var i=0;i<probes.length;i++){
        var p = probes[i];
        var rad = 60;
        var alpha = Math.min(p.irr * 1.2, 0.5);
        var grad = ctx.createRadialGradient(p.x,p.y, 0, p.x,p.y, rad);
        grad.addColorStop(0, 'rgba(255, 200, 100,'+alpha+')');
        grad.addColorStop(1, 'rgba(255, 200, 100, 0)');
        ctx.fillStyle = grad;
        ctx.fillRect(p.x-rad, p.y-rad, rad*2, rad*2);
      }

      ctx.fillStyle = '#556';
      for(var k=0;k<walls.length;k++){
        var w = walls[k];
        ctx.fillRect(w.x, w.y, w.w, w.h);
      }

      for(var i=0;i<probes.length;i++){
        var p = probes[i];
        var v = Math.min(p.irr * 2.5, 1);
        ctx.fillStyle = 'rgb('+Math.round(60+200*v)+','+Math.round(60+170*v)+','+Math.round(80+50*v)+')';
        ctx.beginPath();
        ctx.arc(p.x, p.y, 5, 0, Math.PI*2);
        ctx.fill();
        ctx.strokeStyle = '#222';
        ctx.lineWidth = 1;
        ctx.stroke();
      }

      var grad = ctx.createRadialGradient(light.x, light.y, 0, light.x, light.y, 80);
      grad.addColorStop(0, 'rgba(255,100,100,0.8)');
      grad.addColorStop(1, 'rgba(255,100,100,0)');
      ctx.fillStyle = grad;
      ctx.fillRect(light.x-80, light.y-80, 160, 160);
      ctx.fillStyle = '#ff5050';
      ctx.beginPath();
      ctx.arc(light.x, light.y, 9, 0, Math.PI*2);
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.fillStyle = '#889';
      ctx.font = '12px var(--font-monospace, monospace)';
      ctx.fillText('Room A', 90, 75);
      ctx.fillText('Room B (wall blocks light)', 320, 75);
    }

    function loop(){
      update();
      draw();
      requestAnimationFrame(loop);
    }
    loop();

    function getXY(e){
      var r = cv.getBoundingClientRect();
      var sx = cv.width / r.width;
      var sy = cv.height / r.height;
      var x = (e.touches?e.touches[0].clientX:e.clientX) - r.left;
      var y = (e.touches?e.touches[0].clientY:e.clientY) - r.top;
      return {x: x*sx, y: y*sy};
    }
    cv.addEventListener('mousedown', function(e){
      var p = getXY(e);
      if(Math.abs(p.x-light.x) < 20 && Math.abs(p.y-light.y) < 20){
        light.dragging = true;
      } else {
        light.x = p.x; light.y = p.y;
      }
    });
    cv.addEventListener('mousemove', function(e){
      if(light.dragging){
        var p = getXY(e);
        light.x = Math.max(60, Math.min(W-60, p.x));
        light.y = Math.max(60, Math.min(H-60, p.y));
      }
    });
    cv.addEventListener('mouseup', function(){ light.dragging = false; });
    cv.addEventListener('mouseleave', function(){ light.dragging = false; });
    cv.addEventListener('touchstart', function(e){ e.preventDefault(); light.dragging = true; var p = getXY(e); light.x=p.x; light.y=p.y; }, {passive:false});
    cv.addEventListener('touchmove', function(e){ e.preventDefault(); if(light.dragging){ var p = getXY(e); light.x = Math.max(60, Math.min(W-60, p.x)); light.y = Math.max(60, Math.min(H-60, p.y)); } }, {passive:false});
    cv.addEventListener('touchend', function(){ light.dragging = false; });
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', initDDGI);
  } else {
    initDDGI();
  }
})();
</script>
