      <button id="btn-step" style="background:#1890ff;color:#fff;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">下一帧 ▶</button>
      <button id="btn-spatial" style="background:#52c41a;color:#fff;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">+空间复用</button>
      <button id="btn-reset" style="background:#999;color:#fff;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;">重置</button>
    </div>
  </div>
</div>
<script>
(function(){
  const svg = document.getElementById('restir-flow');
  const statEquiv = document.getElementById('stat-equiv');
  const statCost  = document.getElementById('stat-cost');

  // 状态
  let frame = 0;          // 当前显示帧数 (0=只有当前帧, 1=+1历史, 2=+2历史)
  let spatialK = 0;       // 空间邻居数
  const MAX_FRAMES = 3;

  // 布局常量
  const COLS = 3;         // 显示 3 帧
  const FX = [80, 350, 620];  // 每帧中心 x
  const FY = 100;         // 帧行 y
  const BOX_W = 120, BOX_H = 60;
  const NBR_Y = 210;       // 邻居行 y

  const FRAME_LABELS = ['Frame N-2', 'Frame N-1', 'Frame N'];
  const FRAME_COLORS = ['#ffe7ba', '#bae7ff', '#d9f7be'];
  const FRAME_STROKES= ['#fa8c16', '#1890ff', '#52c41a'];

  function clamp(v, lo, hi){ return Math.max(lo, Math.min(hi, v)); }

  function render(){
    const activeFrames = clamp(frame + 1, 1, MAX_FRAMES); // 1~3 帧可见
    let html = '';

    // 定义箭头 marker
    html += `<defs>
      <marker id="arr-blue" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto">
        <path d="M0,0 L0,6 L8,3 z" fill="#1890ff"/></marker>
      <marker id="arr-green" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto">
        <path d="M0,0 L0,6 L8,3 z" fill="#52c41a"/></marker>
      <marker id="arr-orange" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto">
        <path d="M0,0 L0,6 L8,3 z" fill="#fa8c16"/></marker>
      <marker id="arr-gray" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto">
        <path d="M0,0 L0,6 L8,3 z" fill="#aaa"/></marker>
    </defs>`;

    // 绘制各帧 reservoir box
    for(let i = 0; i < COLS; i++){
      const visible = i >= (COLS - activeFrames);
      const cx = FX[i], cy = FY;
      const x0 = cx - BOX_W/2, y0 = cy - BOX_H/2;
      const alpha = visible ? 1 : 0.18;

      html += `<rect x="${x0}" y="${y0}" width="${BOX_W}" height="${BOX_H}" rx="8"
        fill="${FRAME_COLORS[i]}" stroke="${FRAME_STROKES[i]}" stroke-width="2" opacity="${alpha}"/>`;
      html += `<text x="${cx}" y="${cy-10}" text-anchor="middle" font-size="11" fill="#666" opacity="${alpha}">${FRAME_LABELS[i]}</text>`;
      html += `<text x="${cx}" y="${cy+8}" text-anchor="middle" font-size="13" font-weight="700" fill="#333" opacity="${alpha}">Pixel A</text>`;
      html += `<text x="${cx}" y="${cy+24}" text-anchor="middle" font-size="12" fill="#555" opacity="${alpha}">R${COLS-1-i}</text>`;

      // 帧标签
      html += `<text x="${cx}" y="${y0-10}" text-anchor="middle" font-size="10" fill="#aaa" opacity="${alpha}">${FRAME_LABELS[i]}</text>`;
    }

    // 时间复用箭头（帧间）
    for(let i = 0; i < COLS-1; i++){
      const visible = i >= (COLS - activeFrames) && (i+1) >= (COLS - activeFrames);
      if(!visible) continue;
      const x1 = FX[i] + BOX_W/2 + 4;
      const x2 = FX[i+1] - BOX_W/2 - 4;
      const y  = FY;
      const isTemp = i == COLS-2;
      const color = isTemp ? '#1890ff' : '#fa8c16';
      const label = isTemp ? 'temporal reuse' : 'spatial reuse';
      const mid = (x1 + x2) / 2;
      html += `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="${color}" stroke-width="2"
        stroke-dasharray="${isTemp?'none':'5,3'}" marker-end="url(#arr-${isTemp?'blue':'orange'})"/>`;
      html += `<text x="${mid}" y="${y-10}" text-anchor="middle" font-size="10" fill="${color}">${label}</text>`;
    }

    // 当前帧：新样本 input
    {
      const cx = FX[2], cy = FY;
      html += `<circle cx="${cx}" cy="${cy-50}" r="14" fill="#fff" stroke="#722ed1" stroke-width="2"/>`;
      html += `<text x="${cx}" y="${cy-46}" text-anchor="middle" font-size="10" fill="#722ed1" font-weight="700">new</text>`;
      html += `<line x1="${cx}" y1="${cy-36}" x2="${cx}" y2="${cy-30}" stroke="#722ed1" stroke-width="2" marker-end="url(#arr-gray)"/>`;
      html += `<text x="${cx+20}" y="${cy-48}" font-size="9" fill="#9254de">Initial sample</text>`;
    }

    // 空间邻居（仅在 K>0 时显示）
    if(spatialK > 0){
      const nbrXs = [
        FX[2] - 90, FX[2] - 50, FX[2] + 50, FX[2] + 90
      ].slice(0, spatialK);

      for(let i = 0; i < nbrXs.length; i++){
        const nx = nbrXs[i], ny = NBR_Y;
        html += `<rect x="${nx-36}" y="${ny-20}" width="72" height="40" rx="6"
          fill="#fff7e6" stroke="#fa8c16" stroke-width="1.5"/>`;
        html += `<text x="${nx}" y="${ny-4}" text-anchor="middle" font-size="10" fill="#874d00">Pixel</text>`;
        html += `<text x="${nx}" y="${ny+12}" text-anchor="middle" font-size="9" fill="#aaa">${['B','C','D','E'][i]}（邻居）</text>`;
        // 邻居 → Pixel A (当前帧)
        const tx = FX[2] + (nx < FX[2] ? -BOX_W/2 : BOX_W/2);
        html += `<line x1="${nx}" y1="${ny-20}" x2="${tx}" y2="${FY+BOX_H/2+4}"
          stroke="#52c41a" stroke-width="1.5" stroke-dasharray="4,3" marker-end="url(#arr-green)"/>`;
      }

      // 历史像素也指向邻居（示意 N-1 的邻居）
      if(activeFrames >= 2){
        const midX = (FX[1] + FX[2]) / 2;
        html += `<text x="${midX}" y="${NBR_Y+36}" text-anchor="middle" font-size="10" fill="#52c41a">空间复用 (K=${spatialK})</text>`;
      }
    } else if(activeFrames >= 2){
      html += `<text x="${FX[1]}" y="${NBR_Y+20}" text-anchor="middle" font-size="11" fill="#aaa">← 点击 "+空间复用" 展示邻居 →</text>`;
    }

    // 底部等效样本数标注
    const equiv = activeFrames * (1 + spatialK);
    const W = 1920, H = 1080;
    const total = W * H * equiv;
    html += `<rect x="20" y="230" width="720" height="24" rx="4" fill="#f0f0f0"/>`;
    html += `<text x="380" y="246" text-anchor="middle" font-size="11" fill="#555">
