    svg.innerHTML = html;
    info.textContent = `Step: ${idx} / ${N}  |  w_sum: ${wsum.toFixed(2)}  |  Reservoir.Y: ${chosen>=0?'X'+(chosen+1)+' (w='+weights[chosen]+')':'null'}`;
  }
  function step() {
    if (idx >= N) return;
    wsum += weights[idx];
    if (Math.random() < weights[idx] / wsum) chosen = idx;
    idx++;
    render();
  }
  function reset() {
    if (timer) { clearInterval(timer); timer = null; document.getElementById('wrs-auto').textContent = 'Auto Run'; }
    idx = 0; wsum = 0; chosen = -1; render();
  }
  document.getElementById('wrs-step').onclick = step;
  document.getElementById('wrs-reset').onclick = reset;
  document.getElementById('wrs-auto').onclick = function() {
    if (timer) { clearInterval(timer); timer = null; this.textContent = 'Auto Run'; }
    else {
      this.textContent = 'Pause';
      timer = setInterval(() => {
        if (idx >= N) { clearInterval(timer); timer = null; document.getElementById('wrs-auto').textContent = 'Auto Run'; return; }
        step();
      }, 500);
    }
  };
  reset();
})();
</script>
