// 7. 局部风: 采样噪声 -> 方向 + 旋转扰动
float2 worldUV =position.xz;
float2 localWindUV =worldUV *_LocalWindScale;
localWindUV +=_Time *float2(1,0.7)* _LocalWindSpeed; // 漂移速度
